import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"EmakiStorage","description":"","frontmatter":{},"headers":[],"relativePath":"modules/storage/index.md","filePath":"modules/storage/index.md","lastUpdated":0}`),a={name:`modules/storage/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="emakistorage" tabindex="-1">EmakiStorage <a class="header-anchor" href="#emakistorage" aria-label="Permalink to “EmakiStorage”">​</a></h1><p>EmakiStorage 是 Emaki 系列的 GUI 仓库模块. 你可以把物品存进一个按槽位分格的仓库界面, 每个槽位能放下的数量远超原版堆叠上限, 而且存进去的物品在组件, 附魔, PDC (物品上由插件写入的隐藏数据) 这些额外数据上全部原样保留</p><p>仓库界面由 <code>gui/storage_gui.yml</code> 模板描述; 容量由 <code>config.yml</code>, 权限档位, 命令授予和付费购买共同决定; 其他插件还能通过 CoreLib 动作, 公开 API 和 Bukkit 事件来存取物品或读取仓库信息</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to “基本信息”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>2.0.0</code></td></tr><tr><td>API Jar</td><td><code>emaki-storage-api-2.0.0.jar</code></td></tr><tr><td>主类</td><td><code>emaki.jiuwu.craft.storage.EmakiStoragePlugin</code></td></tr><tr><td>主命令</td><td><code>/emakistorage</code></td></tr><tr><td>别名</td><td><code>/estorage</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>PlaceholderAPI</td></tr><tr><td>描述符基线</td><td><code>api-version: &quot;26.1&quot;</code>, <code>folia-supported: true</code></td></tr><tr><td>Java</td><td>Java 25</td></tr><tr><td>主要权限</td><td><code>emakistorage.use</code> (默认 true), <code>emakistorage.unlock.purchase</code> (默认 true), <code>emakistorage.autopickup</code> (默认 true), <code>emakistorage.reload</code> (op), <code>emakistorage.debug</code> (op), <code>emakistorage.admin</code> (op)</td></tr></tbody></table><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to “功能页面”">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td><code>/emakistorage</code>, <code>/estorage</code> 的子命令, 权限节点与示例</td></tr><tr><td><a href="./configuration.html">配置详解</a></td><td><code>config.yml</code> 的 <code>unlock</code>, <code>behavior</code>, <code>search</code>, <code>persistence</code>, <code>logging</code> 等键</td></tr><tr><td><a href="./capacity.html">容量与缩容</a></td><td><code>capacity</code> 段, 四来源容量, 三级 <code>stackLimit</code> 与缩容溢出策略</td></tr><tr><td><a href="./gui.html">界面与展示</a></td><td><code>gui</code> 与 <code>display</code> 段, <code>gui/storage_gui.yml</code> 模板结构与点击处理规则</td></tr><tr><td><a href="./unlock-costs.html">付费扩容档位</a></td><td><code>unlock_costs.yml</code> 的档位, 逐格计价与支付顺序</td></tr><tr><td><a href="./corelib-actions.html">CoreLib 动作</a></td><td>EmakiStorage 注册到 CoreLib ActionRegistry 的 5 个动作</td></tr><tr><td><a href="./api.html">API 与集成</a></td><td>第三方插件通过 <code>emaki-storage-api</code> 调用仓库的方式与结果模型</td></tr><tr><td><a href="./events.html">事件 API</a></td><td><code>StorageDepositEvent</code>, <code>StorageWithdrawEvent</code>, <code>StorageUnlockEvent</code>, <code>StorageBatchEvent</code> 四个 Bukkit 事件</td></tr><tr><td><a href="./placeholders.html">PlaceholderAPI 占位符</a></td><td><code>emakistorage</code> 扩展的 10 个占位符与求值线程约束</td></tr></tbody></table><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to “核心能力”">​</a></h2><ul><li><strong>单个槽位能存的量很大</strong>: 一个槽位只放一种物品, 数量上限来自三级 <code>stackLimit</code> (单槽上限, 分条目级, 玩家级, 配置级三层), 而不是原版的 64 或 99 堆叠</li><li><strong>物品原样保留</strong>: 判断两个物品是否相同, 用的是完整的 <code>ItemStack#equals</code> 比较 (组件, 附魔, 自定义 PDC 都参与比对), 没有另外引入哈希签名层, 所以材质相同但组件不同的两个物品不会被并成一条</li><li><strong>槽位数量是容量的唯一来源</strong>: 有效槽位 <code>effectiveSlots</code> 由 <code>base_slots</code>, 权限档位, 命令授予, 付费购买这四部分相加后再受上限限制算出, 页数再由槽位数推出来 (<code>ceil(effectiveSlots / 每页格数)</code>), 不会反过来先定页数再算槽位</li><li><strong>两种存入方式走同一套逻辑</strong>: 在展示区任意槽位点击 (光标上带着物品) 和点固定投入口 <code>deposit_slot</code>, 这两条路共用同一套存取逻辑, 容量检查, 过滤, 事件和流水记录都只有一份</li><li><strong>占用率用 1–99 显示</strong>: <code>display.amount_mode: percent</code> 时, 用槽位物品的 <code>amount</code> 字段在 1–99 之间表示占用百分比, 精确数量写进 lore. <code>max_stack_size</code> 组件本身就只接受 1–99, 所以不需要任何数据包技巧</li><li><strong>搜索与排序</strong>: 搜索是子串匹配, 永远不会去编译正则表达式; 排序是一个明确的&quot;整理&quot;操作, 会重新写下条目的先后顺序</li><li><strong>缩容不丢数据</strong>: 你把容量调小导致存的物品超出上限时, 有四种处理策略, 它们都不会造成无法恢复的数据丢失, 也没有提供 <code>drop</code> / <code>delete</code></li><li><strong>流水日志只写不读</strong>: 插件的业务逻辑从不读取日志文件; <code>ADMIN_SET</code>, <code>ADMIN_GIVE</code>, <code>ADMIN_CLEAR</code> 这三类管理员操作一定会被记录</li></ul><h2 id="存档设计" tabindex="-1">存档设计 <a class="header-anchor" href="#存档设计" aria-label="Permalink to “存档设计”">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>实现</th></tr></thead><tbody><tr><td>条目数据</td><td>条目数据存在一个二进制文件 <code>storage.dat</code> 里, 文件头魔数是 <code>EMSTOR</code>, 当前格式版本 <code>2</code>. 文件末尾还带一段预留 (reservation) 记录, 让 API 的预留能跨重启保留下来</td></tr><tr><td>写入策略</td><td>每次保存都把<strong>整个文件重写</strong>, 不是往后追加. 所以每次存完文件都是紧凑的, 也就不用压实工具, 不用统计垃圾比例, 不用修复悬空的 id</td></tr><tr><td>写入顺序</td><td>先在同一个目录写一个 <code>.tmp</code>, 再读回来核对记录条数, 最后一步才整体替换. 如果写入失败, 旧文件保留不动, 并把 tmp 删掉</td></tr><tr><td>逐条目分帧</td><td>每条记录单独打包, 用 Paper 的 <code>ItemStack#serializeAsBytes()</code> / <code>deserializeBytes(byte[])</code>, 记录里带上 <code>DataVersion</code>, 读取时会经过 DataFixer 升级</td></tr><tr><td>损坏隔离</td><td>解不开的记录被单独写到 <code>corrupt/&lt;uuid&gt;-&lt;时间戳&gt;.dat</code>, 剩下的记录照常载入</td></tr><tr><td>可手改数据</td><td><code>meta.yml</code> (文本 YAML, <code>version: 1.0.0</code>) 保存 <code>player_name</code>, <code>granted_slots</code>, <code>purchased_slots</code>, <code>default_stack_limit</code>, <code>sort_mode</code>, <code>auto_pickup</code> 这些可以直接手改的数据; 物品本身还是二进制, 因为 YAML 表达不了一个完整的 <code>ItemStack</code></td></tr></tbody></table><h2 id="文件结构" tabindex="-1">文件结构 <a class="header-anchor" href="#文件结构" aria-label="Permalink to “文件结构”">​</a></h2><p>服务器跑起来后, EmakiStorage 主要用到下面这些文件:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiStorage/</span></span>
<span class="line"><span>├─ config.yml</span></span>
<span class="line"><span>├─ unlock_costs.yml</span></span>
<span class="line"><span>├─ gui/</span></span>
<span class="line"><span>│  ├─ storage_gui.yml</span></span>
<span class="line"><span>│  ├─ editor_browser_gui.yml</span></span>
<span class="line"><span>│  └─ editor_page_gui.yml</span></span>
<span class="line"><span>├─ lang/</span></span>
<span class="line"><span>│  ├─ zh_CN.yml</span></span>
<span class="line"><span>│  └─ en_US.yml</span></span>
<span class="line"><span>├─ data/</span></span>
<span class="line"><span>│  └─ &lt;uuid&gt;/</span></span>
<span class="line"><span>│     ├─ storage.dat</span></span>
<span class="line"><span>│     └─ meta.yml</span></span>
<span class="line"><span>├─ logs/</span></span>
<span class="line"><span>│  └─ &lt;uuid&gt;/</span></span>
<span class="line"><span>│     └─ &lt;yyyy-MM-dd&gt;.log</span></span>
<span class="line"><span>├─ corrupt/</span></span>
<span class="line"><span>└─ exports/</span></span></code></pre></div><table tabindex="0"><thead><tr><th>路径</th><th>说明</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td>主配置, 管界面, 容量, 扩容缩容, 展示, 存取行为, 搜索, 持久化和日志</td></tr><tr><td><code>unlock_costs.yml</code></td><td>付费扩容的价格档位. 属于业务数据文件, 只在文件缺失时释放一次; 升级版本时不会覆盖管理员改过的内容</td></tr><tr><td><code>gui/storage_gui.yml</code></td><td>仓库界面模板. 功能区只需要配 <code>offset</code>, 实际槽位号由 <code>gui.storage_rows</code> 换算出来</td></tr><tr><td><code>lang/*.yml</code></td><td>界面, 命令, 扩容和控制台提示的文案</td></tr><tr><td><code>data/&lt;uuid&gt;/storage.dat</code></td><td>这个玩家的条目数据, 二进制, 每次保存整份重写</td></tr><tr><td><code>data/&lt;uuid&gt;/meta.yml</code></td><td>这个玩家的槽位数, <code>stackLimit</code>, 排序模式和自动拾取开关等可以手改的元数据</td></tr><tr><td><code>logs/&lt;uuid&gt;/&lt;yyyy-MM-dd&gt;.log</code></td><td>存取流水, 每个玩家一个目录, 每天一个文件, 只写不读</td></tr><tr><td><code>corrupt/</code></td><td>解不开的记录放在这里隔离</td></tr><tr><td><code>exports/</code></td><td><code>/estorage export</code> 生成的可读 YAML 导出文件</td></tr></tbody></table><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to “快速开始”">​</a></h2><ol><li>把 <code>EmakiCoreLib-*.jar</code> 与 <code>EmakiStorage-*.jar</code> 放入服务器 <code>plugins/</code></li><li>不要把 <code>emaki-storage-api-*.jar</code> 放进服务器的 <code>plugins/</code> 目录; API Jar 只是给开发者写代码时用的编译依赖</li><li>首次启动后检查 <code>plugins/EmakiStorage/config.yml</code> 与 <code>unlock_costs.yml</code></li><li>打开自己的仓库:</li></ol><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/estorage</span></span></code></pre></div><ol start="5"><li>修改配置后重载配置, 语言与 GUI 模板:</li></ol><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/estorage reload</span></span></code></pre></div><ol start="6"><li>给在线玩家追加槽位并查看容量拆解:</li></ol><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/estorage slot grant Steve 10</span></span>
<span class="line"><span>/estorage info Steve</span></span></code></pre></div><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to “使用提示”">​</a></h2><ul><li><code>gui.deposit_feedback</code> 建议不要设为 <code>none</code>. 两种存入方式混用时, 物品按条目顺序摆放, 可能落到别的页上; 没有反馈玩家会以为物品消失了</li><li><code>emakistorage.slots.&lt;n&gt;</code> 与 <code>emakistorage.stacklimit.&lt;n&gt;</code> 都取所有生效档位里的最大值, 并且<strong>不支持通配</strong></li><li>想缩减容量的话, 把 <code>capacity.base_slots</code> 调小不会吃掉玩家已经授予或购买的槽位, 这三个来源各自单独存档</li><li>缩容溢出的状态不会存进文件, 它是根据容量和占用推算出来的; 目前只有刷新 GUI 视图时才会去算它, 所以在打开界面, 以及每次存取, 翻页, 排序, 搜索之后刷新时会重新算一次</li><li><code>config.yml</code> 注释里出现的 <code>/storage</code> 是历史写法, 命令并未注册该别名, 见 <a href="./commands.html">命令与权限</a></li><li>会改动数据的那些管理命令要求目标玩家在线, 见 <a href="./commands.html">命令与权限</a></li></ul>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};